package org.eclipse.jdt.internal.ui.jarpackagerfat;

import org.eclipse.core.runtime.IPath;
import org.eclipse.core.runtime.Path;
import org.w3c.dom.Document;
import org.w3c.dom.Element;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import java.io.File;

// Minimal FatJarAntExporter for example compilation context
abstract class FatJarAntExporter {
    protected static class SourceInfo {
        public final boolean isJar;
        public final String absPath;
        public SourceInfo(boolean isJar, String absPath) { this.isJar = isJar; this.absPath = absPath; }
    }
    public FatJarAntExporter(Object config, IPath jarLocation, IPath antScriptLocation) { /* empty */ }
    protected String substituteBaseDirs(String absFilename) {
        // Dummy implementation to allow compilation and show substitution
        return "SUBSTITUTED_PATH(" + absFilename + ")";
    }
}

class SomeAntExporter extends FatJarAntExporter {
    public SomeAntExporter(Object config, IPath jarLoc, IPath antScriptLoc) {
        super(config, jarLoc, antScriptLoc);
    }

    public void createAntScript() throws ParserConfigurationException {
        Document document = DocumentBuilderFactory.newInstance().newDocumentBuilder().newDocument();
        String absJarname = "/absolute/path/to/my.jar";
        SourceInfo[] sourceInfos = {
            new SourceInfo(true, "/absolute/path/to/lib1.jar"),
            new SourceInfo(false, "/absolute/path/to/classes")
        };
        String absSubfolder = "/absolute/path/to/temp";

        Element project = document.createElement("project");
        document.appendChild(project);

        Element jar = document.createElement("jar");
        project.appendChild(jar);

        // Target: destfile attribute
        jar.setAttribute("destfile", absJarname);

        // Target: dir attribute (zipfileset)
        File jarFile = new File(sourceInfos[0].absPath);
        Element zipfileset = document.createElement("zipfileset");
        zipfileset.setAttribute("dir", jarFile.getParent());
        zipfileset.setAttribute("includes", jarFile.getName());
        jar.appendChild(zipfileset);

        // Target: dir attribute (fileset)
        Element fileset = document.createElement("fileset");
        fileset.setAttribute("dir", sourceInfos[1].absPath);
        jar.appendChild(fileset);

        // Target: dir attribute (delete)
        Element delete = document.createElement("delete");
        delete.setAttribute("dir", absSubfolder);
        project.appendChild(delete);

        // Target: dir attribute (mkdir)
        Element mkdir = document.createElement("mkdir");
        mkdir.setAttribute("dir", absSubfolder);
        project.appendChild(mkdir);

        // Target: file attribute (copy)
        Element copyFile = document.createElement("copy");
        copyFile.setAttribute("file", sourceInfos[0].absPath);
        project.appendChild(copyFile);

        // Target: todir attribute (copy)
        Element copyToDir = document.createElement("copy");
        copyToDir.setAttribute("todir", absSubfolder);
        project.appendChild(copyToDir);
    }
}

